    foreach(lf_rows($koneksi,$data['read_sql'],$data['read_args']) as $g){$ev=rc_tariff_evidence($koneksi,$g);$values=[unit_label((int)$g['unit_id']),$g['name'],$g['identity'],$g['student_id']?'Siswa':'Pemilik non-siswa',$g['kelas']?:'Tidak tercatat',$g['th_ajaran']?:'Tidak tercatat',(float)$g['native_total'],(float)$g['native_paid'],(float)$g['legacy_paid'],$ev['status'],$ev['tariff'],$ev['remaining'],$ev['reason']];foreach($values as $col=>$v)$sheet->setCellValueExplicit([$col+1,$line],$v,is_int($v)||is_float($v)?\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_NUMERIC:\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);$line++;}
    $sheet->freezePane('A2');$sheet->setAutoFilter('A1:M'.($line-1));$sheet->getStyle('A1:M1')->getFont()->setBold(true);$sheet->getStyle('G2:I'.max(2,$line-1))->getNumberFormat()->setFormatCode('#,##0.00');$sheet->getColumnDimension('B')->setWidth(32);$sheet->getColumnDimension('M')->setWidth(70);$sheet->getStyle('M1:M'.($line-1))->getAlignment()->setWrapText(true);
    header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="riwayat-daftar-ulang.xlsx"');(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');exit;
