<section class="ph-detail-panel"><header class="ph-panel-heading"><h3>Detail Daftar Ulang</h3></header><div class="ph-detail-body"><?php if($chosen):$ev=rc_tariff_evidence($koneksi,$chosen);$receipts=rc_receipts($koneksi,$chosen,$data['source']); ?><h3><?= $e($chosen['name']) ?></h3><p><?= $e($chosen['th_ajaran']?:'Tahun ajaran tidak tercatat') ?> · <?= $e($chosen['kelas']?:'Kelas tidak tercatat') ?></p><section class="ph-payment-box"><h4>Rekap Daftar Ulang</h4><dl class="ph-components"><?php foreach(['Tarif historis disahkan'=>$ev['tariff'],'Pembayaran Legacy'=>$chosen['legacy_paid'],'Sisa historis'=>$ev['remaining']] as $label=>$amount): ?><div><dt><?= $label ?></dt><dd><?= $amount===null?'Belum dapat ditentukan':payment_history_money($amount) ?></dd></div><?php endforeach; ?></dl><strong><?= $e($ev['status']) ?></strong><p><?= $e($ev['reason']) ?></p><?php if(isset($ev['source_tariff'])): ?><p>Referensi tarif sumber: <?= payment_history_money($ev['source_tariff']) ?></p><?php endif; ?></section><?php if($chosen['native_count']): ?><section class="ph-payment-box"><h4>Tagihan Operasional</h4><p>Tagihan <?= payment_history_money($chosen['native_total']) ?> · Terbayar <?= payment_history_money((float)$chosen['native_paid']+(float)$chosen['legacy_paid']) ?> · Sisa <?= payment_history_money(max(0,$chosen['native_total']-$chosen['native_paid']-($ev['tariff']!==null?$chosen['legacy_paid']:0))) ?></p><p>Pembayaran native dan kredit Legacy dengan bukti kewajiban yang lengkap menentukan sisa ini.</p></section><?php endif; ?><h3>Rincian Pembayaran · <?= count($receipts) ?></h3><?php foreach($receipts as $p):$token=payment_return_create((int)$p['id'],(int)$p['unit_id'],array_replace($query,['selected'=>$chosen['id'],'selected_unit'=>$chosen['unit_id']])); ?><section class="ph-payment-box"><h4><?= $p['id']<0?'Legacy':'SistemSPP' ?> · <?= $e(payment_time_label($p)) ?></h4><p>Daftar Ulang <strong><?= payment_history_money($p['du_amount']) ?></strong></p><?php if(abs($p['du_amount']-$p['total_jumlah'])>.001): ?><p>Total transaksi campuran <?= payment_history_money($p['total_jumlah']) ?></p><?php endif; ?><div class="ph-detail-actions"><a class="btn btn-ghost btn-sm" href="lihat.php?<?= $e(http_build_query(['all_periods'=>'1','selected'=>$p['id'],'selected_unit'=>$p['unit_id']])) ?>">Lihat Transaksi</a><a class="btn btn-ghost btn-sm" target="_blank" rel="noopener" href="../laporan/cetak_struk.php?id=<?= (int)$p['id'] ?>">Cetak Bukti Transaksi</a><?php if(!unit_all_readonly()&&hasRole(['admin','kasir'])): ?><a class="btn btn-ghost btn-sm" href="<?= $e(payment_return_edit_url($token,(int)$p['id'])) ?>">Edit</a><?php endif; ?></div></section><?php endforeach; ?><?php else: ?><p>Pilih pemilik untuk melihat rincian.</p><?php endif; ?></div></section></div></div></main></div><script src="../assets/js/app.js"></script></body></html>
